import{c as s,Q as n,j as t,m as e}from"./chunks/framework.DOi4mjdC.js";const p="/assets/zh-cn_formulaimage_0000002046262966.BlofzASl.png",l="data:image/png;base64,",m=JSON.parse('{"title":"Normalize","description":"","frontmatter":{},"headers":[{"level":1,"title":"Normalize","slug":"normalize"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/归一化操作/Normalize.md","filePath":"api/SIMD-API/高阶API/归一化操作/Normalize.md"}'),i={name:"api/SIMD-API/高阶API/归一化操作/Normalize.md"};function o(r,a,c,d,h,A){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="normalize" tabindex="-1">Normalize <a class="header-anchor" href="#normalize" aria-label="Permalink to &quot;Normalize&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p><a href="./LayerNorm.html">LayerNorm</a>中，已知均值和方差，计算shape为[A，R]的输入数据的标准差的倒数rstd和y，其计算公式如下：</p><p><img src="'+p+'" alt=""></p><p><img src="'+l+`" alt=""></p><p>其中，E和Var分别代表输入在R轴的均值，方差，γ为缩放系数，β为平移系数，ε为防除零的权重系数。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt; typename U, typename T, bool isReuseSource = false, const NormalizeConfig&amp; config = NLCFG_NORM&gt;</span></span>
<span class="line"><span>__aicore__ inline void Normalize(const LocalTensor&lt;T&gt;&amp; output, const LocalTensor&lt;float&gt;&amp; outputRstd, const LocalTensor&lt;float&gt;&amp; inputMean, const LocalTensor&lt;float&gt;&amp; inputVariance, const LocalTensor&lt;T&gt;&amp; inputX, const LocalTensor&lt;U&gt;&amp; gamma, const LocalTensor&lt;U&gt;&amp; beta, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const float epsilon, const NormalizePara&amp; para)</span></span></code></pre></div></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt; typename U, typename T, bool isReuseSource = false, const NormalizeConfig&amp; config = NLCFG_NORM&gt;</span></span>
<span class="line"><span>__aicore__ inline void Normalize(const LocalTensor&lt;T&gt;&amp; output, const LocalTensor&lt;float&gt;&amp; outputRstd, const LocalTensor&lt;float&gt;&amp; inputMean, const LocalTensor&lt;float&gt;&amp; inputVariance, const LocalTensor&lt;T&gt;&amp; inputX, const LocalTensor&lt;U&gt;&amp; gamma, const LocalTensor&lt;U&gt;&amp; beta, const float epsilon, const NormalizePara&amp; para)</span></span></code></pre></div></li></ul><p>由于该接口的内部实现中涉及复杂的计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间支持<strong>接口框架申请</strong>和开发者<strong>通过sharedTmpBuffer入参传入</strong>两种方式。</p><ul><li><p>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</p></li><li><p>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li></ul><p>接口框架申请的方式，开发者需要预留临时空间；通过sharedTmpBuffer传入的情况，开发者需要为tensor申请空间。临时空间大小BufferSize的获取方式如下：通过<a href="./Normalize-Tiling.html">Normalize Tiling</a>中提供的GetNormalizeMaxMinTmpSize接口获取所需最大和最小临时空间大小，最小空间可以保证功能正确，最大空间用于提升性能。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>U</td><td>beta，gamma操作数的数据类型。不同型号支持的数据类型请参考支持的数据类型。</td></tr><tr><td>T</td><td>output，inputX操作数的数据类型。不同型号支持的数据类型请参考支持的数据类型。</td></tr><tr><td>isReuseSource</td><td>该参数预留，传入默认值false即可。</td></tr><tr><td>config</td><td>配置Normalize接口中输入输出相关信息。NormalizeConfig类型，定义如下方代码所示，其中参数的含义如下。 reducePattern：当前仅支持ReducePattern::AR模式，表示输入的内轴R轴为reduce计算轴。aLength：用于描述输入的A轴大小。支持的取值如下：-1：默认值。取接口参数para中的aLength作为A轴大小。1：支持outputRstd数据非对齐搬出，支持inputMean，inputVariance数据非对齐搬入。aLength为其它取值时，不支持上述三个输入输出的非对齐搬入和非对齐搬出。该取值需要与接口参数para中的aLength数值一致。请注意，仅在Ascend 950PR/Ascend 950DT上支持该取值。其它值：该值需要与接口参数para中的aLength数值一致。 isNoBeta：计算时，输入beta是否使用。false：默认值，Normalize计算中使用输入beta。true：Normalize计算中不使用输入beta。此时，公式中与beta相关的计算被省略。 isNoGamma：可选输入gamma是否使用。false：默认值，Normalize计算中使用可选输入gamma。true：Normalize计算中不使用输入gamma。此时，公式中与gamma相关的计算被省略。 isOnlyOutput：是否只输出y，不输出标准差的倒数rstd。当前该参数仅支持取值为false，表示y和rstd的结果全部输出。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct NormalizeConfig {</span></span>
<span class="line"><span>    ReducePattern reducePattern = ReducePattern::AR;</span></span>
<span class="line"><span>    int32_t aLength = -1;</span></span>
<span class="line"><span>    bool isNoBeta = false;</span></span>
<span class="line"><span>    bool isNoGamma = false;</span></span>
<span class="line"><span>    bool isOnlyOutput = false;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>output</td><td>输出</td><td>目的操作数，shape为[A, R]，LocalTensor数据结构的定义请参考LocalTensor。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>outputRstd</td><td>输出</td><td>标准差的倒数，shape为[A]，LocalTensor数据结构的定义请参考LocalTensor。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>inputMean</td><td>输入</td><td>均值，shape为[A]，LocalTensor数据结构的定义请参考LocalTensor。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>inputVariance</td><td>输入</td><td>方差，shape为[A]，LocalTensor数据结构的定义请参考LocalTensor。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>inputX</td><td>输入</td><td>源操作数，shape为[A, R]，LocalTensor数据结构的定义请参考LocalTensor。inputX的数据类型需要与目的操作数保持一致，尾轴长度需要32B对齐。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>gamma</td><td>输入</td><td>缩放系数，shape为[R]，LocalTensor数据结构的定义请参考LocalTensor。gamma的数据类型精度不低于源操作数的数据类型精度。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>beta</td><td>输入</td><td>平移系数，shape为[R]，LocalTensor数据结构的定义请参考LocalTensor。beta的数据类型精度不低于源操作数的数据类型精度。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>共享缓冲区，用于存放API内部计算产生的临时数据。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。共享缓冲区大小的获取方式请参考Normalize Tiling。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>epsilon</td><td>输入</td><td>防除零的权重系数。</td></tr><tr><td>para</td><td>输入</td><td>Normalize计算所需的参数信息。NormalizePara类型，定义如下方代码所示，其中参数的含义如下。 aLength：指定输入inputX的A轴长度。rLength：指定输入inputX的R轴长度。rLengthWithPadding：指定输入inputX的R轴对齐后的长度，该值是32B对齐的。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct NormalizePara {</span></span>
<span class="line"><span>    uint32_t aLength;</span></span>
<span class="line"><span>    uint32_t rLength;</span></span>
<span class="line"><span>    uint32_t rLengthWithPadding;</span></span>
<span class="line"><span>};</span></span></code></pre></div><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>操作数地址对齐要求请参见<a href="./../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>缩放系数gamma和平移系数beta的数据类型精度必须不低于源操作数inputX的数据类型精度。比如，inputX的数据类型是half，gamma、beta的数据类型可以是half或者float，精度不低于inputX。比如，inputX的数据类型是bfloat16_t，gamma、beta的数据类型可以是bfloat16_t或者float，精度不低于inputX。</p></li><li><p>src和dst的Tensor空间不可以复用。</p></li><li><p>输入仅支持ND格式。</p></li><li><p>R轴不支持切分。</p></li><li><p>支持的数据类型</p><p>Ascend 950PR/Ascend 950DT，支持的数据类型为：half、bfloat16_t、float。</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为: half、float。</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为: half、float。</p><p>Atlas 推理系列产品AI Core，支持的数据类型为: half、float。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// yLocal: 输出归一化后的结果 y，shape 为 [A, R]</span></span>
<span class="line"><span>// rstdLocal: 输出标准差的倒数（1 / sqrt(variance + epsilon)），shape 为 [A]</span></span>
<span class="line"><span>// meanLocal: 输入的均值，shape 为 [A]</span></span>
<span class="line"><span>// varianceLocal: 输入的方差，shape 为 [A]</span></span>
<span class="line"><span>// xLocal: 输入数据 X，shape 为 [A, R]，数据类型与 output 一致</span></span>
<span class="line"><span>// gammaLocal: 缩放参数 gamma，shape 为 [R]</span></span>
<span class="line"><span>// betaLocal: 平移参数 beta，shape 为 [R]</span></span>
<span class="line"><span>// epsilon: 防除零系数</span></span>
<span class="line"><span>// para: 包含 A、R 维度信息的 NormalizePara 结构体</span></span>
<span class="line"><span>// config: Normalize 配置参数，指定是否跳过 gamma/beta、reduce 模式等</span></span>
<span class="line"><span></span></span>
<span class="line"><span>constexpr AscendC::NormalizeConfig CONFIG {</span></span>
<span class="line"><span>    .reducePattern = AscendC::ReducePattern::AR,</span></span>
<span class="line"><span>    .aLength = -1,</span></span>
<span class="line"><span>    .isNoBeta = isNoBeta,</span></span>
<span class="line"><span>    .isNoGamma = isNoGamma,</span></span>
<span class="line"><span>    .isOnlyOutput = false</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 使用 Normalize 接口执行层归一化计算 </span></span>
<span class="line"><span>AscendC::Normalize&lt;DTYPE_Y, DTYPE_X, false, CONFIG&gt;(</span></span>
<span class="line"><span>    yLocal,          // 输出：归一化结果 y，shape [A, R]</span></span>
<span class="line"><span>    rstdLocal,       // 输出：标准差倒数 rstd，shape [A]</span></span>
<span class="line"><span>    meanLocal,       // 输入：均值 mean，shape [A]</span></span>
<span class="line"><span>    varianceLocal,   // 输入：方差 variance，shape [A]</span></span>
<span class="line"><span>    xLocal,          // 输入：原始数据 X，shape [A, R]</span></span>
<span class="line"><span>    gammaLocal,      // 输入：缩放系数γ，shape [R]</span></span>
<span class="line"><span>    betaLocal,       // 输入：平移系数β，shape [R]</span></span>
<span class="line"><span>    epsilon,         // 输入：防除零系数ε</span></span>
<span class="line"><span>    para             // 输入：Tiling 参数，包含 aLength、rLength、rLengthWithPadding</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>示例结果如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(srcLocal, shape:[8, 8]): </span></span>
<span class="line"><span>[  0.  1.  2.  3.  4.  5.  6.  7.</span></span>
<span class="line"><span>   8.  9. 10. 11. 12. 13. 14. 15.</span></span>
<span class="line"><span>  16. 17. 18. 19. 20. 21. 22. 23.</span></span>
<span class="line"><span>  24. 25. 26. 27. 28. 29. 30. 31.</span></span>
<span class="line"><span>  32. 33. 34. 35. 36. 37. 38. 39.</span></span>
<span class="line"><span>  40. 41. 42. 43. 44. 45. 46. 47.</span></span>
<span class="line"><span>  48. 49. 50. 51. 52. 53. 54. 55.</span></span>
<span class="line"><span>  56. 57. 58. 59. 60. 61. 62. 63. ]</span></span>
<span class="line"><span>输入数据(meanLocal, shape:[8]): </span></span>
<span class="line"><span>[ 0. 1. 2. 3. 4. 5. 6. 7. ]</span></span>
<span class="line"><span>输入数据(varianceLocal, shape:[8]): </span></span>
<span class="line"><span>[ 0. 1. 2. 3. 4. 5. 6. 7. ]</span></span>
<span class="line"><span>输入数据(gammaLocal, shape:[8]): </span></span>
<span class="line"><span>[ 1. 1. 1. 1. 1. 1. 1. 1. ]</span></span>
<span class="line"><span>输入数据(betaLocal, shape:[8]): </span></span>
<span class="line"><span>[ 1. 1. 1. 1. 1. 1. 1. 1. ]</span></span>
<span class="line"><span>输出数据(yLocal): </span></span>
<span class="line"><span>[ 1.0 32.622772 64.245544 95.868324 127.4911 159.11388 190.73665 222.35942 </span></span>
<span class="line"><span>  7.996503 8.996003 9.995503 10.995004 11.994504 12.994005 13.9935055 14.993006 </span></span>
<span class="line"><span>  10.897021 11.603951 12.310882 13.017812 13.724742 14.431672 15.138602 15.845532 </span></span>
<span class="line"><span>  13.122336 13.699591 14.276845 14.854099 15.431353 16.008606 16.585861 17.163115 </span></span>
<span class="line"><span>  14.998251 15.498188 15.998126 16.498064 16.998001 17.497938 17.997875 18.497814 </span></span>
<span class="line"><span>  16.65091 17.09808 17.545248 17.992416 18.439585 18.886755 19.333923 19.781092 </span></span>
<span class="line"><span>  18.144999 18.553213 18.961428 19.369642 19.777857 20.186071 20.594284 21.002499 </span></span>
<span class="line"><span>  19.518936 19.896873 20.27481 20.652748 21.030685 21.408623 21.78656 22.164497 ]</span></span>
<span class="line"><span>输出数据(rstdLocal): </span></span>
<span class="line"><span>[ 31.622774    0.9995004   0.7069301   0.5772541   0.49993753  0.44716886  0.40821427  0.37793747 ]</span></span></code></pre></div>`,28)])])}const u=s(i,[["render",o]]);export{m as __pageData,u as default};
